import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry layernorm_affine_fwd(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 batch_size,
    .param .u32 S_total,
    .param .f32 eps_param
)
{
    .reg .pred   %p0, %p1, %p2, %pg, %p_vec;
    .reg .b32    %r_tid, %r_bid, %r_S, %r_i, %r_stride, %r_tmp, %cnt, %cnt2, %cntsum, %lane, %warp, %mask, %nwarps, %r_S4, %r_iv, %r_stride4, %r_tail_i;
    .reg .b64    %x, %w, %b, %y, %x_base, %y_base, %addr, %off64, %byte_off, %tmp64, %saddr, %saddr2, %sbase, %sbase2, %off2, %sbase3, %saddr3, %saddr3b;
    .reg .f32    %sum, %sumsq, %val, %val2, %mean, %m2, %Sf, %var, %vareps, %std, %invstd, %eps;
    .reg .f32    %xv, %wv, %bv, %t, %yv, %delta, %delta2, %cntf, %cnt2f, %cntsumf, %ratio, %kterm;
    .reg .f32    %x0, %x1, %x2, %x3, %w0, %w1, %w2, %w3, %b0, %b1, %b2, %b3, %t0, %t1, %t2, %t3, %y0, %y1, %y2, %y3;
    .shared .align 4 .b32 sh_sum[256];
    .shared .align 4 .b32 sh_sumsq[256];
    .shared .align 4 .b32 sh_cnt[256];
    // Load parameters
    ld.param.u64 %x, [x_ptr];
    ld.param.u64 %w, [w_ptr];
    ld.param.u64 %b, [b_ptr];
    ld.param.u64 %y, [y_ptr];
    ld.param.u32 %r_S, [S_total];
    ld.param.f32 %eps, [eps_param];
    // Thread/block info
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_bid, %ctaid.x;
    mov.u32 %r_stride, %ntid.x;
    // Compute base offsets for this sample
    mul.wide.u32 %tmp64, %r_S, %r_bid;     // elements offset = S * blockIdx.x
    shl.b64 %byte_off, %tmp64, 2;          // bytes = elements * 4
    add.s64 %x_base, %x, %byte_off;
    add.s64 %y_base, %y, %byte_off;
    // Initialize Welford partials
    mov.f32 %mean, 0f00000000;
    mov.f32 %m2,   0f00000000;
    mov.u32 %cnt,  0;
    // First pass: Welford per-thread accumulation
    mov.u32 %r_i, %r_tid;
L_sum_loop:
    setp.ge.u32 %p0, %r_i, %r_S;
    @%p0 bra L_after_sum;
    mul.wide.u32 %off64, %r_i, 4;
    add.s64 %addr, %x_base, %off64;
    ld.global.f32 %val, [%addr];
    add.u32 %cnt, %cnt, 1;
    sub.f32 %delta, %val, %mean;
    cvt.rn.f32.u32 %cntf, %cnt;
    div.rn.f32 %delta2, %delta, %cntf;
    add.f32 %mean, %mean, %delta2;
    sub.f32 %delta2, %val, %mean;
    fma.rn.f32 %m2, %delta, %delta2, %m2;
    add.u32 %r_i, %r_i, %r_stride;
    bra L_sum_loop;
L_after_sum:
    // Warp-level Welford reduction via shfl to reduce barriers
    mov.u32 %lane, %laneid;
    shr.u32 %warp, %r_tid, 5;             // warp id
    mov.u32 %mask, 0xffffffff;
    // Intra-warp reduce
    // offset 16
    shfl.sync.down.b32 %val,  %mean, 16, 0x1f, %mask;
    shfl.sync.down.b32 %val2, %m2,   16, 0x1f, %mask;
    shfl.sync.down.b32 %cnt2, %cnt,  16, 0x1f, %mask;
    setp.lt.u32 %p1, %lane, 16;
    @%p1 setp.ne.u32 %p0, %cnt2, 0;
    and.pred %p2, %p1, %p0;
    @%p2 cvt.rn.f32.u32 %cntf, %cnt;
    @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
    @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
    @%p2 sub.f32 %delta, %val, %mean;
    @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
    @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
    @%p2 mul.f32 %kterm, %delta, %delta;
    @%p2 mul.f32 %kterm, %kterm, %cntf;
    @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
    @%p2 add.f32 %m2, %m2, %val2;
    @%p2 add.u32 %cnt, %cnt, %cnt2;
    // offset 8
    shfl.sync.down.b32 %val,  %mean, 8, 0x1f, %mask;
    shfl.sync.down.b32 %val2, %m2,   8, 0x1f, %mask;
    shfl.sync.down.b32 %cnt2, %cnt,  8, 0x1f, %mask;
    setp.lt.u32 %p1, %lane, 24;
    @%p1 setp.ne.u32 %p0, %cnt2, 0;
    and.pred %p2, %p1, %p0;
    @%p2 cvt.rn.f32.u32 %cntf, %cnt;
    @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
    @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
    @%p2 sub.f32 %delta, %val, %mean;
    @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
    @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
    @%p2 mul.f32 %kterm, %delta, %delta;
    @%p2 mul.f32 %kterm, %kterm, %cntf;
    @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
    @%p2 add.f32 %m2, %m2, %val2;
    @%p2 add.u32 %cnt, %cnt, %cnt2;
    // offset 4
    shfl.sync.down.b32 %val,  %mean, 4, 0x1f, %mask;
    shfl.sync.down.b32 %val2, %m2,   4, 0x1f, %mask;
    shfl.sync.down.b32 %cnt2, %cnt,  4, 0x1f, %mask;
    setp.lt.u32 %p1, %lane, 28;
    @%p1 setp.ne.u32 %p0, %cnt2, 0;
    and.pred %p2, %p1, %p0;
    @%p2 cvt.rn.f32.u32 %cntf, %cnt;
    @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
    @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
    @%p2 sub.f32 %delta, %val, %mean;
    @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
    @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
    @%p2 mul.f32 %kterm, %delta, %delta;
    @%p2 mul.f32 %kterm, %kterm, %cntf;
    @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
    @%p2 add.f32 %m2, %m2, %val2;
    @%p2 add.u32 %cnt, %cnt, %cnt2;
    // offset 2
    shfl.sync.down.b32 %val,  %mean, 2, 0x1f, %mask;
    shfl.sync.down.b32 %val2, %m2,   2, 0x1f, %mask;
    shfl.sync.down.b32 %cnt2, %cnt,  2, 0x1f, %mask;
    setp.lt.u32 %p1, %lane, 30;
    @%p1 setp.ne.u32 %p0, %cnt2, 0;
    and.pred %p2, %p1, %p0;
    @%p2 cvt.rn.f32.u32 %cntf, %cnt;
    @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
    @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
    @%p2 sub.f32 %delta, %val, %mean;
    @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
    @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
    @%p2 mul.f32 %kterm, %delta, %delta;
    @%p2 mul.f32 %kterm, %kterm, %cntf;
    @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
    @%p2 add.f32 %m2, %m2, %val2;
    @%p2 add.u32 %cnt, %cnt, %cnt2;
    // offset 1
    shfl.sync.down.b32 %val,  %mean, 1, 0x1f, %mask;
    shfl.sync.down.b32 %val2, %m2,   1, 0x1f, %mask;
    shfl.sync.down.b32 %cnt2, %cnt,  1, 0x1f, %mask;
    setp.lt.u32 %p1, %lane, 31;
    @%p1 setp.ne.u32 %p0, %cnt2, 0;
    and.pred %p2, %p1, %p0;
    @%p2 cvt.rn.f32.u32 %cntf, %cnt;
    @%p2 cvt.rn.f32.u32 %cnt2f, %cnt2;
    @%p2 add.f32 %cntsumf, %cntf, %cnt2f;
    @%p2 sub.f32 %delta, %val, %mean;
    @%p2 div.rn.f32 %ratio, %cnt2f, %cntsumf;
    @%p2 fma.rn.f32 %mean, %delta, %ratio, %mean;
    @%p2 mul.f32 %kterm, %delta, %delta;
    @%p2 mul.f32 %kterm, %kterm, %cntf;
    @%p2 fma.rn.f32 %m2, %kterm, %ratio, %m2;
    @%p2 add.f32 %m2, %m2, %val2;
    @%p2 add.u32 %cnt, %cnt, %cnt2;
    // Write per-warp partials (lane 0 of each warp)
    setp.eq.u32 %p0, %lane, 0;
    @%p0 mov.u64 %sbase,  sh_sum;
    @%p0 mov.u64 %sbase2, sh_sumsq;
    @%p0 mov.u64 %sbase3, sh_cnt;
    @%p0 mul.wide.u32 %off64, %warp, 4;
    @%p0 add.s64 %saddr,  %sbase,  %off64;
    @%p0 st.shared.f32 [%saddr], %mean;
    @%p0 add.s64 %saddr2, %sbase2, %off64;
    @%p0 st.shared.f32 [%saddr2], %m2;
    @%p0 add.s64 %saddr3, %sbase3, %off64;
    @%p0 st.shared.u32 [%saddr3], %cnt;
    bar.sync 0;
    // Final reduction by warp 0 over per-warp partials
    shr.u32 %nwarps, %r_stride, 5;
    setp.eq.u32 %p0, %warp, 0;
    @%p0 mov.f32 %mean, 0f00000000;
    @%p0 mov.f32 %m2,   0f00000000;
    @%p0 mov.u32 %cnt,  0;
    @%p0 setp.lt.u32 %p1, %lane, %nwarps;
    @%p0 mov.u64 %sbase,  sh_sum;
    @%p0 mov.u64 %sbase2, sh_sumsq;
    @%p0 mov.u64 %sbase3, sh_cnt;
    @%p0 mul.wide.u32 %off64, %lane, 4;
    @%p0 add.s64 %saddr,  %sbase,  %off64;
    @%p0 add.s64 %saddr2, %sbase2, %off64;
    @%p0 add.s64 %saddr3, %sbase3, %off64;
    and.pred %pg, %p0, %p1;
    @%pg ld.shared.f32 %mean, [%saddr];
    @%pg ld.shared.f32 %m2,   [%saddr2];
    @%pg ld.shared.u32 %cnt,  [%saddr3];
    @%p0 mov.u32 %mask, 0xffffffff;
    // Intra-warp reduce across nwarps entries
    @%p0 shfl.sync.down.b32 %val,  %mean, 16, 0x1f, %mask;
    @%p0 shfl.sync.down.b32 %val2, %m2,   16, 0x1f, %mask;
    @%p0 shfl.sync.down.b32 %cnt2, %cnt,  16, 0x1f, %mask;
    @%p0 setp.lt.u32 %p1, %lane, 16;
    and.pred %pg, %p0, %p1;
    @%pg setp.ne.u32 %p2, %cnt2, 0;
    and.pred %pg, %p0, %p2;
    @%pg cvt.rn.f32.u32 %cntf, %cnt;
    @%pg cvt.rn.f32.u32 %cnt2f, %cnt2;
    @%pg add.f32 %cntsumf, %cntf, %cnt2f;
    @%pg sub.f32 %delta, %val, %mean;
    @%pg div.rn.f32 %ratio, %cnt2f, %cntsumf;
    @%pg fma.rn.f32 %mean, %delta, %ratio, %mean;
    @%pg mul.f32 %kterm, %delta, %delta;
    @%pg mul.f32 %kterm, %kterm, %cntf;
    @%pg fma.rn.f32 %m2, %kterm, %ratio, %m2;
    @%pg add.f32 %m2, %m2, %val2;
    @%pg add.u32 %cnt, %cnt, %cnt2;
    @%p0 shfl.sync.down.b32 %val,  %mean, 8, 0x1f, %mask;
    @%p0 shfl.sync.down.b32 %val2, %m2,   8, 0x1f, %mask;
    @%p0 shfl.sync.down.b32 %cnt2, %cnt,  8, 0x1f, %mask;
    @%p0 setp.lt.u32 %p1, %lane, 24;
    and.pred %pg, %p0, %p1;
    @%pg setp.ne.u32 %p2, %cnt2, 0;
    and.pred %pg, %p0, %p2;
    @%pg cvt.rn.f32.u32 %cntf, %cnt;
    @%pg cvt.rn.f32.u32 %cnt2f, %cnt2;
    @%pg add.f32 %cntsumf, %cntf, %cnt2f;
    @%pg sub.f32 %delta, %val, %mean;
    @%pg div.rn.f32 %ratio, %cnt2f, %cntsumf;
    @%pg fma.rn.f32 %mean, %delta, %ratio, %mean;
    @%pg mul.f32 %kterm, %delta, %delta;
    @%pg mul.f32 %kterm, %kterm, %cntf;
    @%pg fma.rn.f32 %m2, %kterm, %ratio, %m2;
    @%pg add.f32 %m2, %m2, %val2;
    @%pg add.u32 %cnt, %cnt, %cnt2;
    @%p0 shfl.sync.down.b32 %val,  %mean, 4, 0x1f, %mask;
    @%p0 shfl.sync.down.b32 %val2, %m2,   4, 0x1f, %mask;
    @%p0 shfl.sync.down.b32 %cnt2, %cnt,  4, 0x1f, %mask;
    @%p0 setp.lt.u32 %p1, %lane, 28;
    and.pred %pg, %p0, %p1;
    @%pg setp.ne.u32 %p2, %cnt2, 0;
    and.pred %pg, %p0, %p2;
    @%pg cvt.rn.f32.u32 %cntf, %cnt;
    @%pg cvt.rn.f32.u32 %cnt2f, %cnt2;
    @%pg add.f32 %cntsumf, %cntf, %cnt2f;
    @%pg sub.f32 %delta, %val, %mean;
    @%pg div.rn.f32 %ratio, %cnt2f, %cntsumf;
    @%pg fma.rn.f32 %mean, %delta, %ratio, %mean;
    @%pg mul.f32 %kterm, %delta, %delta;
    @%pg mul.f32 %kterm, %kterm, %cntf;
    @%pg fma.rn.f32 %m2, %kterm, %ratio, %m2;
    @%pg add.f32 %m2, %m2, %val2;
    @%pg add.u32 %cnt, %cnt, %cnt2;
    @%p0 shfl.sync.down.b32 %val,  %mean, 2, 0x1f, %mask;
    @%p0 shfl.sync.down.b32 %val2, %m2,   2, 0x1f, %mask;
    @%p0 shfl.sync.down.b32 %cnt2, %cnt,  2, 0x1f, %mask;
    @%p0 setp.lt.u32 %p1, %lane, 30;
    and.pred %pg, %p0, %p1;
    @%pg setp.ne.u32 %p2, %cnt2, 0;
    and.pred %pg, %p0, %p2;
    @%pg cvt.rn.f32.u32 %cntf, %cnt;
    @%pg cvt.rn.f32.u32 %cnt2f, %cnt2;
    @%pg add.f32 %cntsumf, %cntf, %cnt2f;
    @%pg sub.f32 %delta, %val, %mean;
    @%pg div.rn.f32 %ratio, %cnt2f, %cntsumf;
    @%pg fma.rn.f32 %mean, %delta, %ratio, %mean;
    @%pg mul.f32 %kterm, %delta, %delta;
    @%pg mul.f32 %kterm, %kterm, %cntf;
    @%pg fma.rn.f32 %m2, %kterm, %ratio, %m2;
    @%pg add.f32 %m2, %m2, %val2;
    @%pg add.u32 %cnt, %cnt, %cnt2;
    @%p0 shfl.sync.down.b32 %val,  %mean, 1, 0x1f, %mask;
    @%p0 shfl.sync.down.b32 %val2, %m2,   1, 0x1f, %mask;
    @%p0 shfl.sync.down.b32 %cnt2, %cnt,  1, 0x1f, %mask;
    @%p0 setp.lt.u32 %p1, %lane, 31;
    and.pred %pg, %p0, %p1;
    @%pg setp.ne.u32 %p2, %cnt2, 0;
    and.pred %pg, %p0, %p2;
    @%pg cvt.rn.f32.u32 %cntf, %cnt;
    @%pg cvt.rn.f32.u32 %cnt2f, %cnt2;
    @%pg add.f32 %cntsumf, %cntf, %cnt2f;
    @%pg sub.f32 %delta, %val, %mean;
    @%pg div.rn.f32 %ratio, %cnt2f, %cntsumf;
    @%pg fma.rn.f32 %mean, %delta, %ratio, %mean;
    @%pg mul.f32 %kterm, %delta, %delta;
    @%pg mul.f32 %kterm, %kterm, %cntf;
    @%pg fma.rn.f32 %m2, %kterm, %ratio, %m2;
    @%pg add.f32 %m2, %m2, %val2;
    @%pg add.u32 %cnt, %cnt, %cnt2;
    // Compute mean and invstd (lane 0 of warp 0)
    @%p0 setp.eq.u32 %p1, %lane, 0;
    and.pred %pg, %p0, %p1;
    @%pg cvt.rn.f32.u32 %Sf, %r_S;
    @%pg div.rn.f32 %var, %m2, %Sf;          // population variance
    @%pg max.f32 %var, %var, 0f00000000;
    @%pg add.f32 %vareps, %var, %eps;
    @%pg sqrt.rn.f32 %std, %vareps;
    @%pg rcp.rn.f32 %invstd, %std;
    @%pg st.shared.f32 [sh_sum], %mean;
    @%pg st.shared.f32 [sh_sumsq], %invstd;
    bar.sync 0;
    // Load broadcasted mean and invstd
    ld.shared.f32 %mean, [sh_sum];
    ld.shared.f32 %invstd, [sh_sumsq];
    // Second pass: normalize, scale (weight), and shift (bias)
    // Decide on vectorized path when addresses are 16B aligned and S >= 4
    and.b64 %tmp64, %x_base, 0xf;
    setp.eq.u64 %p0, %tmp64, 0;
    and.b64 %tmp64, %y_base, 0xf;
    setp.eq.u64 %p1, %tmp64, 0;
    and.pred %p0, %p0, %p1;
    and.b64 %tmp64, %w, 0xf;
    setp.eq.u64 %p1, %tmp64, 0;
    and.pred %p0, %p0, %p1;
    and.b64 %tmp64, %b, 0xf;
    setp.eq.u64 %p1, %tmp64, 0;
    and.pred %p0, %p0, %p1;
    setp.gt.u32 %p1, %r_S, 3;
    and.pred %p_vec, %p0, %p1;
    @%p_vec bra L_norm_vec;
    // Scalar fallback
    mov.u32 %r_i, %r_tid;
L_norm_scalar:
    setp.ge.u32 %p0, %r_i, %r_S;
    @%p0 bra L_done;
    mul.wide.u32 %off64, %r_i, 4;
    add.s64 %addr, %x_base, %off64;
    ld.global.f32 %xv, [%addr];
    add.s64 %addr, %w, %off64;
    ld.global.f32 %wv, [%addr];
    add.s64 %addr, %b, %off64;
    ld.global.f32 %bv, [%addr];
    sub.f32 %t, %xv, %mean;
    mul.f32 %t, %t, %invstd;
    mul.f32 %t, %t, %wv;
    add.f32 %yv, %t, %bv;
    add.s64 %addr, %y_base, %off64;
    st.global.f32 [%addr], %yv;
    add.u32 %r_i, %r_i, %r_stride;
    bra L_norm_scalar;
L_norm_vec:
    // Process main body with vectorized loads/stores
    and.b32 %r_S4, %r_S, 0xfffffffc;
    shl.b32 %r_iv, %r_tid, 2;
    shl.b32 %r_stride4, %r_stride, 2;
L_vec_loop:
    setp.ge.u32 %p0, %r_iv, %r_S4;
    @%p0 bra L_vec_after;
    mul.wide.u32 %off64, %r_iv, 4;
    add.s64 %addr, %x_base, %off64;
    ld.global.v4.f32 {%x0,%x1,%x2,%x3}, [%addr];
    add.s64 %addr, %w, %off64;
    ld.global.v4.f32 {%w0,%w1,%w2,%w3}, [%addr];
    add.s64 %addr, %b, %off64;
    ld.global.v4.f32 {%b0,%b1,%b2,%b3}, [%addr];
    sub.f32 %t0, %x0, %mean;
    mul.f32 %t0, %t0, %invstd;
    fma.rn.f32 %y0, %t0, %w0, %b0;
    sub.f32 %t1, %x1, %mean;
    mul.f32 %t1, %t1, %invstd;
    fma.rn.f32 %y1, %t1, %w1, %b1;
    sub.f32 %t2, %x2, %mean;
    mul.f32 %t2, %t2, %invstd;
    fma.rn.f32 %y2, %t2, %w2, %b2;
    sub.f32 %t3, %x3, %mean;
    mul.f32 %t3, %t3, %invstd;
    fma.rn.f32 %y3, %t3, %w3, %b3;
    add.s64 %addr, %y_base, %off64;
    st.global.v4.f32 [%addr], {%y0,%y1,%y2,%y3};
    add.u32 %r_iv, %r_iv, %r_stride4;
    bra L_vec_loop;
L_vec_after:
    // Tail elements [S4, S)
    mov.u32 %r_tail_i, %r_tid;
L_vec_tail_loop:
    add.u32 %r_tmp, %r_tail_i, %r_S4;
    setp.ge.u32 %p0, %r_tmp, %r_S;
    @%p0 bra L_done;
    mul.wide.u32 %off64, %r_tmp, 4;
    add.s64 %addr, %x_base, %off64;
    ld.global.f32 %xv, [%addr];
    add.s64 %addr, %w, %off64;
    ld.global.f32 %wv, [%addr];
    add.s64 %addr, %b, %off64;
    ld.global.f32 %bv, [%addr];
    sub.f32 %t, %xv, %mean;
    mul.f32 %t, %t, %invstd;
    mul.f32 %t, %t, %wv;
    add.f32 %yv, %t, %bv;
    add.s64 %addr, %y_base, %off64;
